/* Question bank, part 2: 40 PSM-focused (modules 9–12) and 40 PSPO-focused
   (modules 13–16) questions. Same authoring keys as questions-shared.js. */
(function (root) {
  'use strict';
  var SSS = root.SSS = root.SSS || {};
  var sg = SSS.sg, S = SSS.SRC;

  SSS.addQuestions([
    /* ---------- Module 9: Scrum Master effectiveness ---------- */
    { id: '09-01', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "Which of the following is the Scrum Master accountable for?",
      o: ["Establishing Scrum as defined in the Scrum Guide","Maximizing the value of the product","Assigning tasks to Developers","Approving each Increment before release"],
      c: [0],
      e: "The Scrum Master is accountable for establishing Scrum as defined in the Scrum Guide and for the Scrum Team's effectiveness.",
      x: "Maximizing value belongs to the Product Owner; task assignment belongs to the Developers; Scrum defines no Increment approval step.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '09-02', v: 2, d: 'f', t: 'multi', b: 'rule',
      s: "Which two are ways the Scrum Master serves the Product Owner?",
      o: ["Helping find techniques for effective Product Goal definition and Product Backlog management","Reordering the Product Backlog without the Product Owner's agreement when they are busy","Helping establish empirical product planning for a complex environment","Deciding release dates"],
      c: [0,2],
      e: "The Scrum Master helps with techniques for the Product Goal and backlog management, helps the team understand the need for clear items, helps establish empirical product planning, and facilitates stakeholder collaboration as requested or needed.",
      x: "The Product Owner may delegate ordering work but remains accountable. Reordering without their agreement is taking over, not authorized delegation. Release timing is a product decision, not a Scrum Master service.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '09-03', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "The Scrum Master is accountable for the Scrum Team's effectiveness.",
      c: true,
      e: "The Scrum Master is accountable for the team's effectiveness, achieved by enabling the team to improve its practices within the Scrum framework.",
      x: "This does not make the Scrum Master the team's manager; effectiveness comes from enabling, not directing.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '09-04', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "A newly involved executive believes the Sprint Review is where they sign off on the team's work. What should the Scrum Master do?",
      o: ["Let the executive sign off, since it keeps them engaged","Teach the executive the purpose of the Sprint Review and invite them to collaborate on what to do next","Exclude the executive from the Sprint Review","Ask the Product Owner to hold a separate sign-off meeting"],
      c: [1],
      e: "The executive lacks knowledge of the event's purpose, so teaching fits. The Review is a working session, not an approval gate, and stakeholder participation is valuable.",
      x: "Accepting a sign-off model distorts the event; exclusion loses useful input; a separate sign-off meeting adds a gate Scrum does not need.",
      sup: [{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#increment","section":"Increment"}],
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#sprint-review","section":"Sprint Review"} },
    { id: '09-05', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "Two Developers ask the Scrum Master to decide which of their technical approaches the team should use. What is the most appropriate response?",
      o: ["Choose the approach with less risk","Ask the Product Owner to decide","Help the Developers reach their own decision, for example by facilitating a short comparison","Escalate to the engineering manager"],
      c: [2],
      e: "How to turn backlog items into an Increment is the Developers' decision. The Scrum Master supports self-management by helping them decide rather than deciding for them.",
      x: "Deciding for them, or passing it to the Product Owner or a manager, removes ownership from the people doing the work.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#topic-three-how-will-the-chosen-work-get-done","section":"Sprint Planning, Topic Three"} },
    { id: '09-06', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "How does the 2020 Scrum Guide describe Scrum Masters?",
      o: ["Project managers for the Scrum Team","True leaders who serve the Scrum Team and the larger organization","Administrators of the Scrum process","Representatives of management within the team"],
      c: [1],
      e: "The Guide describes Scrum Masters as true leaders who serve the Scrum Team and the larger organization.",
      x: "The other descriptions imply authority over the team or a purely administrative role.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '09-07', v: 1, d: 'f', t: 'multi', b: 'rule',
      s: "Which two are ways the Scrum Master serves the Scrum Team?",
      o: ["Coaching team members in self-management and cross-functionality","Assigning tasks to balance the workload","Ensuring all Scrum events take place and are positive, productive and kept within the timebox","Writing the Sprint Backlog for the Developers"],
      c: [0,2],
      e: "The Scrum Master coaches self-management and cross-functionality, helps the team focus on high-value Increments, causes impediments to be removed, and ensures events take place effectively.",
      x: "Assigning tasks and writing the Sprint Backlog are the Developers' responsibilities.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '09-08', v: 1, d: 'a', t: 'tf', b: 'rule',
      s: "Ensuring that Scrum events take place means the Scrum Master must personally facilitate every event.",
      c: false,
      e: "The Scrum Master ensures events happen and are positive, productive and timeboxed. That does not require facilitating each one; the Daily Scrum, for example, belongs to the Developers.",
      x: "Facilitating everything can create dependence and weaken self-management.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '09-09', v: 1, d: 'c', t: 'single', b: 'judgment',
      s: "A Scrum Master spends most of each day updating the team board, scheduling meetings and taking notes for the Developers. What is the most likely effect?",
      o: ["The team becomes more self-managing because it has more time","The team may become dependent on the Scrum Master and less able to manage its own work","The Product Owner gains more authority over the Sprint","There is no effect, because these tasks are part of the Scrum Master accountability"],
      c: [1],
      e: "Taking over the team's own coordination work can feel helpful but tends to reduce self-management. The Scrum Master's effectiveness is measured through the team's capability.",
      x: "Administrative support is not one of the Scrum Master's accountabilities, and it does not shift authority to the Product Owner.",
      src: {"label":"Navigating Impediments","url":"https://www.scrum.org/resources/navigating-impediments","section":"Who should remove impediments for the Scrum Team?","verifiedOn":"2026-10-14","sourceSupport":"Direct removal of every impediment can create dependency; the Scrum Master enables self-management and may intervene in organizational obstacles.","authorityType":"scrum-org-learning-practice"} },
    { id: '09-10', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "Which is the best indicator of a Scrum Master's effectiveness?",
      o: ["The number of meetings the Scrum Master facilitates","How well the Scrum Team improves and delivers valuable Increments that meet the Definition of Done","How many impediments the Scrum Master personally removes","Whether the team's velocity increases every Sprint"],
      c: [1],
      e: "The Scrum Master is accountable for the team's effectiveness, so the team's improvement and its ability to deliver valuable, Done Increments are the most meaningful signals.",
      x: "Activity counts and velocity trends measure busyness or output, not effectiveness.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },

    /* ---------- Module 10: Self-management and cross-functionality ---------- */
    { id: '10-01', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "Who decides how the selected Product Backlog items are turned into an Increment?",
      o: ["The Product Owner","The Scrum Master","The Developers","The Developers, subject to the Scrum Master's approval"],
      c: [2],
      e: "How this is done is at the sole discretion of the Developers; no one else tells them how to turn items into Increments.",
      x: "Neither the Product Owner nor the Scrum Master directs or approves the Developers' approach.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#topic-three-how-will-the-chosen-work-get-done","section":"Sprint Planning, Topic Three"} },
    { id: '10-02', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "A Developer's line manager instructs them to spend half the Sprint on another department's project. What should happen first?",
      o: ["The Developer complies quietly to avoid conflict","The Developer makes the request transparent to the Scrum Team so the impact on the Sprint Goal can be discussed with the Product Owner, and the Scrum Master helps address it with the manager","The Scrum Master cancels the Sprint","The Product Owner removes the Developer from the team"],
      c: [1],
      e: "Making the impact visible protects transparency and lets the team and Product Owner respond. Conflicting demands from outside the team are an organizational impediment the Scrum Master can help resolve.",
      x: "Silent compliance hides a threat to the Sprint Goal; only the Product Owner can cancel a Sprint, and only if the goal becomes obsolete.",
      sup: [{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#the-sprint","section":"The Sprint"}],
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '10-03', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "Cross-functional means every Developer must be able to do every type of work the team needs.",
      c: false,
      e: "Cross-functional describes the team as a whole having all necessary skills. Members often share or acquire skills, but not everyone must do everything.",
      x: "Requiring universal skills is a misreading of the term.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-team","section":"Scrum Team"} },
    { id: '10-04', v: 1, d: 'a', t: 'multi', b: 'rule',
      s: "In a self-managing Scrum Team, which two decisions belong to the Developers?",
      o: ["Who works on which task during the Sprint","The Product Goal","How to turn selected items into a Done Increment","The order of the Product Backlog"],
      c: [0,2],
      e: "Self-managing teams decide who does what, when and how. The Developers own the plan for the Sprint.",
      x: "The Product Goal and backlog order are the Product Owner's accountability.",
      sup: [{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"}],
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-team","section":"Scrum Team"} },
    { id: '10-05', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "The Developers are accountable for holding each other accountable as:",
      o: ["Employees of the same department","Professionals","Subordinates of the Scrum Master","Individual contributors with separate goals"],
      c: [1],
      e: "One Developer accountability is holding each other accountable as professionals.",
      x: "The other options imply hierarchy or separate goals, which conflict with a cohesive Scrum Team.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#developers","section":"Developers"} },
    { id: '10-06', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "A new team keeps asking the Scrum Master who should fix each defect. What should the Scrum Master do?",
      o: ["Assign each defect to the most experienced Developer","Ask the Product Owner to assign them","Coach the Developers to decide among themselves how to handle defects","Create a rotation and enforce it"],
      c: [2],
      e: "Deciding who does what is part of self-management. A new team may need coaching to build that habit.",
      x: "Assigning or enforcing a scheme for them keeps the team dependent.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '10-07', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "Because the Scrum Team is self-managing, it may ignore the Definition of Done when it chooses to.",
      c: false,
      e: "Self-management operates within the framework. The Developers are required to conform to the Definition of Done.",
      x: "Self-management covers who, when and how — not abandoning the quality commitment.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#commitment-definition-of-done","section":"Commitment: Definition of Done"} },
    { id: '10-08', v: 1, d: 'c', t: 'single', b: 'judgment',
      s: "Several Developers feel one teammate is regularly not contributing to the Sprint Goal. Who should address this first?",
      o: ["The teammate's line manager","The Developers themselves, with the Scrum Master coaching if needed","The Product Owner","Human Resources"],
      c: [1],
      e: "Developers hold each other accountable as professionals. Addressing it within the team first supports self-management; the Scrum Master can coach the conversation and help if it cannot be resolved.",
      x: "Going straight to managers or HR bypasses the team's own accountability. The Product Owner does not manage Developers.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#developers","section":"Developers"} },
    { id: '10-09', v: 1, d: 'a', t: 'multi', b: 'judgment',
      s: "Which two are constructive ways for managers to support a self-managing Scrum Team?",
      o: ["Helping remove organizational impediments the team cannot resolve","Assigning daily tasks to each Developer","Investing in the skills and environment the team needs","Approving the Sprint Backlog before work starts"],
      c: [0,2],
      e: "The Guide says Scrum Teams are structured and empowered by the organization to manage their own work. Managers help by shaping that environment, not by directing the work.",
      x: "Task assignment and approval of the Developers' plan undermine self-management.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-team","section":"Scrum Team"} },
    { id: '10-10', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "According to the Scrum Guide, Scrum Teams are structured and empowered by the organization to:",
      o: ["Manage their own work","Set their own budgets","Hire their own Product Owner","Define their own version of Scrum"],
      c: [0],
      e: "Scrum Teams are structured and empowered by the organization to manage their own work.",
      x: "Budgets, hiring and redefining the framework are outside this statement.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-team","section":"Scrum Team"} },

    /* ---------- Module 11: Facilitation, coaching, and impediments ---------- */
    { id: '11-01', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "Regarding impediments, the Scrum Master serves the team by:",
      o: ["Personally removing every impediment","Causing the removal of impediments to the Scrum Team's progress","Recording impediments for management to review","Deciding which impediments the team should ignore"],
      c: [1],
      e: "The Scrum Master is accountable for causing the removal of impediments — ensuring they get removed, which may include enabling the team to remove them itself.",
      x: "Removing everything personally can weaken self-management; recording or filtering impediments does not resolve them.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '11-02', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "The Developers cannot agree on a coding standard and the debate is slowing work. What should the Scrum Master do first?",
      o: ["Impose an industry-standard style guide","Help the Developers work through the disagreement, for example by facilitating a structured discussion","Ask the Product Owner to choose","Tell them to defer the decision to next Sprint"],
      c: [1],
      e: "The decision is within the Developers' authority. Facilitating or coaching helps them resolve it themselves.",
      x: "Imposing an answer or handing it to the Product Owner takes ownership away; deferring leaves the impediment in place.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '11-03', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "Impediments should be raised only at the Daily Scrum.",
      c: false,
      e: "The Daily Scrum helps identify impediments, but they can and should be raised whenever they are found.",
      x: "Waiting for an event to raise a blocker delays adaptation.",
      src: {"label":"Navigating Impediments","url":"https://www.scrum.org/resources/navigating-impediments","section":"When should team members raise impediments?","verifiedOn":"2026-10-14","sourceSupport":"Blockers should be raised early; Developers need not wait for the Daily Scrum or Retrospective.","authorityType":"scrum-org-learning-practice"} },
    { id: '11-04', v: 1, d: 'a', t: 'multi', b: 'judgment',
      s: "Which two impediments most likely need the Scrum Master to work with the wider organization?",
      o: ["A monthly approval board holds every release for weeks","Two Developers disagree about how to split a task","An HR policy rewards individual output and discourages collaboration","The team's automated tests are slow and the team can fix them"],
      c: [0,2],
      e: "Approval processes and HR policies are outside the team's authority. Removing barriers between stakeholders and Scrum Teams is part of serving the organization.",
      x: "Task disagreements and fixable tooling issues are within the team's self-management.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '11-05', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "The Scrum Master facilitates stakeholder collaboration:",
      o: ["At every Sprint Review without exception","As requested or needed","Only when the Product Owner is absent","Never; stakeholders work only with the Product Owner"],
      c: [1],
      e: "Facilitating stakeholder collaboration as requested or needed is one way the Scrum Master serves the Product Owner.",
      x: "It is neither mandatory at every event nor forbidden.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '11-06', v: 1, d: 'f', t: 'single', b: 'concept',
      s: "What best describes facilitation by a Scrum Master?",
      o: ["Leading a group to the Scrum Master's preferred decision","Helping a group achieve its purpose by providing structure while staying neutral on the content","Taking notes and distributing minutes","Ensuring every person speaks for the same amount of time"],
      c: [1],
      e: "Facilitation supports a group's own decision-making process. The group owns the outcome.",
      x: "Steering to a preferred outcome is not neutral; note-taking and equal speaking time are tactics, not the essence.",
      src: {"label":"Comparing Facilitation, Coaching, Mentoring and Teaching","url":"https://www.scrum.org/resources/comparing-facilitation-coaching-mentoring-and-teaching","section":"Facilitation","verifiedOn":"2026-10-14","sourceSupport":"An impartial process expert enables the group to achieve its purpose; the facilitator does not impose a subject-matter position.","authorityType":"scrum-org-learning-practice"} },
    { id: '11-07', v: 1, d: 'a', t: 'tf', b: 'rule',
      s: "\"Causing the removal of impediments\" means the Scrum Master must personally fix every impediment the team reports.",
      c: false,
      e: "The wording emphasizes ensuring impediments are removed. Often the best action is helping the team remove the impediment itself.",
      x: "Fixing everything personally can create dependence.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '11-08', v: 1, d: 'c', t: 'single', b: 'judgment',
      s: "A disagreement between two Developers has turned into personal criticism in team discussions, and others have stopped contributing. What should the Scrum Master do?",
      o: ["Wait for the team to sort it out, since it is self-managing","Intervene to help the people involved address the conflict, because it is damaging respect and openness on the team","Remove one of the Developers from the team","Ask the Product Owner to mediate"],
      c: [1],
      e: "Self-management does not mean ignoring conflict that is harming the team. The Scrum Master is accountable for effectiveness and can help restore respect and openness.",
      x: "Inaction allows harm to continue; removing people is not the Scrum Master's decision; the Product Owner's focus is product value.",
      sup: [{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"}],
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-values","section":"Scrum Values"} },
    { id: '11-09', v: 1, d: 'a', t: 'single', b: 'concept',
      s: "Which statement best distinguishes coaching from teaching?",
      o: ["Coaching shares knowledge; teaching asks questions","Coaching helps people find their own answers; teaching provides knowledge they do not yet have","They are the same thing","Coaching is only for managers; teaching is only for Developers"],
      c: [1],
      e: "Teaching fits a knowledge gap; coaching helps people who can solve the problem to discover and own the solution.",
      x: "The first option reverses them; the others are inaccurate.",
      src: {"label":"Comparing Facilitation, Coaching, Mentoring and Teaching","url":"https://www.scrum.org/resources/comparing-facilitation-coaching-mentoring-and-teaching","section":"Coaching; Teaching","verifiedOn":"2026-10-14","sourceSupport":"Coaching draws on recipients' experiences and capabilities; teaching supplies knowledge, information and skills.","authorityType":"scrum-org-learning-practice"} },
    { id: '11-10', v: 2, d: 'f', t: 'multi', b: 'rule',
      s: "According to the Scrum Guide, which two are benefits of the Daily Scrum?",
      o: ["Identifying impediments","Providing status to management","Promoting quick decision-making","A manager or Scrum Master assigning the Developers' tasks"],
      c: [0,2],
      e: "Daily Scrums improve communication, identify impediments, promote quick decision-making and eliminate the need for other meetings.",
      x: "The Daily Scrum is not a management status report or a place for a manager or Scrum Master to assign work. Developers may coordinate who does what while adapting their own plan.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#daily-scrum","section":"Daily Scrum"} },

    /* ---------- Module 12: Organizational support and integrated practice ---------- */
    { id: '12-01', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "Which is a way the Scrum Master serves the organization?",
      o: ["Leading, training and coaching the organization in its Scrum adoption","Writing performance reviews for Developers","Setting the product's budget","Ordering the Product Backlog for multiple teams"],
      c: [0],
      e: "The Scrum Master serves the organization by leading, training and coaching its Scrum adoption, planning and advising implementations, helping people enact empiricism, and removing barriers.",
      x: "Performance reviews and budgets are not Scrum accountabilities; backlog ordering belongs to the Product Owner.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '12-02', v: 1, d: 'f', t: 'multi', b: 'rule',
      s: "Which two are listed in the Scrum Guide as ways the Scrum Master serves the organization?",
      o: ["Planning and advising Scrum implementations within the organization","Approving project budgets","Removing barriers between stakeholders and Scrum Teams","Managing Developers' career progression"],
      c: [0,2],
      e: "Both appear in the Guide's list, along with leading, training and coaching adoption, and helping people understand and enact an empirical approach.",
      x: "Budgets and career management are not part of the Scrum Master accountability.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '12-03', v: 2, d: 'a', t: 'tf', b: 'judgment',
      s: "A Done feature requested by customers can still reduce product value if its ongoing costs outweigh the benefits it produces.",
      c: true,
      e: "Meeting the Definition of Done establishes quality, not net value. Consider expected customer benefit alongside development, maintenance, support and other lifetime costs, and inspect results.",
      x: "Customer requests and feature counts alone do not prove value. Costs and outcomes need evidence; a feature is not automatically valuable because it is Done.",
      sup: [{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#commitment-definition-of-done","section":"Commitment: Definition of Done"}],
      src: {"label":"Product Cost","url":"https://www.scrum.org/resources/product-cost","section":"What is Product Cost?; Understanding Product Cost","verifiedOn":"2026-10-14","sourceSupport":"Direct and indirect lifetime costs include development, maintenance, support, employee wages, tools and overhead. Cost can be balanced with learning, risk and expected benefit.","authorityType":"scrum-org-learning-practice"} },
    { id: '12-04', v: 1, d: 'a', t: 'single', b: 'rule',
      s: "A second Scrum Team is joining work on the same product. A manager suggests giving it its own Product Owner and Product Backlog. What should the Scrum Master advise?",
      o: ["Agree, as it keeps each team independent","Both teams should share the same Product Goal, Product Backlog and Product Owner","Each team should have its own backlog but share a Product Owner","Merge the teams into one 15-person team"],
      c: [1],
      e: "Multiple Scrum Teams on the same product share one Product Goal, Product Backlog and Product Owner.",
      x: "Separate backlogs or owners fragment value decisions; a 15-person team is larger than the typical size the Guide describes.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-team","section":"Scrum Team"} },
    { id: '12-05', v: 1, d: 'c', t: 'single', b: 'judgment',
      s: "A department head wants to drop the Sprint Review because stakeholders already receive a weekly status email. What is the best Scrum Master response?",
      o: ["Agree; the email provides the same information","Explain that the Review is a collaborative inspection that can change the Product Backlog, which an email cannot replace, and work on making the Review more valuable for stakeholders","Replace the Review with a longer Retrospective","Let the Developers decide whether to hold it"],
      c: [1],
      e: "The Review is a working session to inspect the outcome and adapt. Removing it changes the framework and loses an opportunity to inspect and adapt with stakeholders.",
      x: "A one-way email is not collaboration; the Retrospective has a different purpose; holding Scrum's events is not optional.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#sprint-review","section":"Sprint Review"} },
    { id: '12-06', v: 2, d: 'a', t: 'single', b: 'judgment',
      s: "Two stakeholders demand different Launchpad features. How can the Scrum Master best help the Product Owner make a useful decision?",
      o: ["Choose the request from the most senior stakeholder","Help clarify customer outcomes, compare expected benefits and costs, and facilitate an evidence-based discussion; the Product Owner remains accountable for ordering","Divide every Sprint equally between the requests","Promise both features by the requested date before discussing capacity"],
      c: [1],
      e: "The Scrum Master supports stakeholder collaboration and empirical product planning. Customer evidence and transparent trade-offs help the Product Owner order work without transferring accountability.",
      x: "Seniority, automatic equal allocation and unsupported promises do not establish value. Facilitation helps people make their own decisions rather than taking over.",
      sup: [{"label":"Customer Outcomes","url":"https://www.scrum.org/resources/customer-outcomes","section":"Determining customer outcomes - getting started; Conclusion","verifiedOn":"2026-10-14","sourceSupport":"Asking customers about their goals and challenges supports discovery of desired outcomes. This does not mandate one discovery technique for all products.","authorityType":"scrum-org-learning-practice"},{"label":"Product Cost","url":"https://www.scrum.org/resources/product-cost","section":"What is Product Cost?; Understanding Product Cost","verifiedOn":"2026-10-14","sourceSupport":"Direct and indirect lifetime costs include development, maintenance, support, employee wages, tools and overhead. Cost can be balanced with learning, risk and expected benefit.","authorityType":"scrum-org-learning-practice"},{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"}],
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '12-07', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "When several Scrum Teams work on one product, their work must be integrated so that the Increments work together.",
      c: true,
      e: "Each Increment is additive to all prior Increments and thoroughly verified, ensuring all Increments work together; teams on one product share a Definition of Done.",
      x: "Leaving integration until later creates hidden undone work.",
      sup: [{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#commitment-definition-of-done","section":"Commitment: Definition of Done"}],
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#increment","section":"Increment"} },
    { id: '12-08', v: 2, d: 'a', t: 'single', b: 'judgment',
      s: "How might a Scrum Master help a Product Owner establish empirical product planning?",
      o: ["By imposing a fixed 12-month plan that ignores actual results","By helping the Product Owner use actual delivery data and Sprint Review feedback to update forecasts and plans","By committing the team to a fixed release date","By removing uncertain items from the Product Backlog"],
      c: [1],
      e: "Empirical planning relies on what has actually happened and adapts as more is learned. The Scrum Master helps the Product Owner adopt that approach.",
      x: "Long-range plans can be useful when they incorporate evidence and remain adaptable. Fixed commitments that ignore new learning undermine empiricism; removing uncertainty from a list does not eliminate it.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '12-09', v: 1, d: 'a', t: 'multi', b: 'judgment',
      s: "Which two situations suggest the Scrum Master should focus on organizational barriers?",
      o: ["Done Increments wait weeks for a separate department to approve releases","The Developers decide to try pair programming","A company policy prevents customers from attending Sprint Reviews","The Product Owner reorders the backlog after a Sprint Review"],
      c: [0,2],
      e: "Both are barriers between the Scrum Team and value or feedback that lie outside the team's authority.",
      x: "Trying a new practice and reordering after a Review are healthy, expected behaviors.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-master","section":"Scrum Master"} },
    { id: '12-10', v: 1, d: 'c', t: 'single', b: 'judgment',
      s: "The organization wants the Scrum Master to also write the Developers' annual performance reviews. What concern should the Scrum Master raise?",
      o: ["None; this gives the Scrum Master useful authority","Developers may become less open about problems with someone who evaluates them, which can reduce transparency and self-management","It would require the Scrum Master to attend the Daily Scrum","It would make the Scrum Master accountable for product value"],
      c: [1],
      e: "Combining evaluative authority with a serving role can discourage openness and create hierarchy within the team. Raising this helps the organization understand the trade-off.",
      x: "Authority over individuals is not part of the Scrum Master role, and the other options are unrelated consequences.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-team","section":"Scrum Team"} },

    /* ---------- Module 13: Product vision, goals, and strategy ---------- */
    { id: '13-01', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "The Product Owner is accountable for:",
      o: ["Maximizing the value of the product resulting from the work of the Scrum Team","Managing the Developers' work","Ensuring Scrum is understood and enacted","Delivering all requested features on time"],
      c: [0],
      e: "The Product Owner is accountable for maximizing the value of the product resulting from the Scrum Team's work, and for effective Product Backlog management.",
      x: "The Developers manage their own work; the Scrum Master establishes Scrum; delivering all requests is output, not value.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '13-02', v: 2, d: 'f', t: 'single', b: 'rule',
      s: "Who is accountable for developing and explicitly communicating the Product Goal?",
      o: ["The Scrum Master","The Product Owner","The Developers","Senior stakeholders"],
      c: [1],
      e: "Developing and explicitly communicating the Product Goal is part of the Product Owner's Product Backlog management accountability.",
      x: "The Product Owner may delegate this work to others but remains accountable. Collaboration or delegation does not transfer the accountability.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '13-03', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "The Product Goal is in the Product Backlog.",
      c: true,
      e: "The Guide states the Product Goal is in the Product Backlog, and the rest of the backlog emerges to define what will fulfill it.",
      x: "Treating the goal as separate from the backlog weakens the link between direction and work.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#commitment-product-goal","section":"Commitment: Product Goal"} },
    { id: '13-04', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "Which Product Goal is most outcome-oriented?",
      o: ["Deliver 20 new reporting features this year","Small-business customers file quarterly taxes in under 30 minutes without contacting support","Migrate the reporting module to a new framework","Complete the roadmap approved by the steering committee"],
      c: [1],
      e: "It describes a future state for customers that the team can plan against and measure, leaving room to discover the best solution.",
      x: "The others describe outputs, technical activities or plan completion, which do not show whether value was created.",
      src: {"label":"Customer Outcomes","url":"https://www.scrum.org/resources/customer-outcomes","section":"What are customer outcomes?","verifiedOn":"2026-10-14","sourceSupport":"Customer results are distinguished from tangible outputs. Outcome-oriented goals enable measuring benefit and leave solution choices open.","authorityType":"scrum-org-learning-practice"} },
    { id: '13-05', v: 1, d: 'f', t: 'multi', b: 'rule',
      s: "Which two are defined in the Scrum Guide?",
      o: ["Product Goal","Product vision statement","Sprint Goal","Product roadmap"],
      c: [0,2],
      e: "The Product Goal and Sprint Goal are commitments defined in the Guide.",
      x: "Vision statements and roadmaps are useful Product Owner practices but are not part of the Scrum framework.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-artifacts","section":"Scrum Artifacts"} },
    { id: '13-06', v: 1, d: 'a', t: 'single', b: 'rule',
      s: "Evidence shows the current Product Goal is no longer worth pursuing. What can the Product Owner do?",
      o: ["Nothing; the team must fulfill the current goal first","Abandon it and then take on a new Product Goal","Keep it but add a second Product Goal","Ask the Scrum Master for permission to change it"],
      c: [1],
      e: "The team must fulfill or abandon one Product Goal before taking on the next. Abandoning a goal that no longer makes sense is a valid, empirical decision.",
      x: "Persisting wastes effort; running two goals at once is not allowed; the Scrum Master does not approve product decisions.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#commitment-product-goal","section":"Commitment: Product Goal"} },
    { id: '13-07', v: 2, d: 'f', t: 'tf', b: 'concept',
      s: "A product vision describes the product's purpose, the value it aims to deliver and who should benefit; it is more than a fixed list of features.",
      c: true,
      e: "Scrum.org describes product vision as direction that helps the Scrum Team and stakeholders understand the product's intended purpose and value. The Product Owner develops it with input from others.",
      x: "A feature list specifies outputs. Vision guides choices and can evolve through inspection and adaptation; it is a supplemental practice, not an additional Scrum Guide commitment.",
      src: {"label":"What is a Product Vision","url":"https://www.scrum.org/resources/what-product-vision","section":"Opening explanation","verifiedOn":"2026-10-14","sourceSupport":"A Product Vision states product purpose and intended value/beneficiaries, incorporates team/stakeholder input and exists in business/product strategy context.","authorityType":"scrum-org-learning-practice"} },
    { id: '13-08', v: 2, d: 'c', t: 'single', b: 'judgment',
      s: "A Product Owner manages only one screen, which has no independently valuable customer outcome, and cannot influence the wider onboarding experience. What is the main concern?",
      o: ["The Product Owner has too much authority","A product boundary that narrow limits the Product Owner's ability to make meaningful value decisions","The Developers will have too little work","The Sprint Review will be too short"],
      c: [1],
      e: "In this situation the boundary prevents meaningful decisions about the end-to-end customer outcome. A small product can be valid when it delivers a clear outcome; a single screen is not automatically invalid.",
      x: "The concern is too little scope for value decisions, not too much authority; workload and Review length are secondary.",
      sup: [{"label":"What is a Product?","url":"https://www.scrum.org/resources/what-product-1","section":"Opening explanation","verifiedOn":"2026-10-14","sourceSupport":"Products deliver valuable customer outcomes and include objects, digital experiences, services and combinations. Size or screen count alone does not establish a valid or invalid product.","authorityType":"scrum-org-learning-practice"},{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#commitment-product-goal","section":"Commitment: Product Goal"}],
      src: {"label":"Why Is Scrum All About Products?","url":"https://www.scrum.org/resources/blog/why-scrum-all-about-products","section":"Defining Product; Product provides clarity and focus.","verifiedOn":"2026-10-14","sourceSupport":"Dave West's July 21, 2023 blog connects product boundaries, customers and outcomes; it provides interpretation, not a categorical minimum product size rule.","authorityType":"author-blog-interpretation"} },
    { id: '13-09', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "How can a Product Owner best understand what customers need?",
      o: ["Rely on the feature requests the sales team collects","Engage directly with customers and users, and validate assumptions with evidence from real use","Ask the Developers to decide what customers want","Copy the features of the leading competitor"],
      c: [1],
      e: "Direct engagement and evidence reduce the risk of building the wrong thing. Requests are inputs, not proof of value.",
      x: "Relying on second-hand requests, delegating the question entirely, or copying competitors skip validation.",
      sup: [{"label":"How to Succeed with Product Discovery and Validation","url":"https://www.scrum.org/resources/blog/how-succeed-product-discovery-and-validation","section":"How to do Product Discovery right?; The importance of validation with evidence","verifiedOn":"2026-10-14","sourceSupport":"Alex Ballarin Latre's June 3, 2024 blog recommends user research, prototype tests, metrics and controlled experiments; these are contextual techniques.","authorityType":"author-blog-interpretation"}],
      src: {"label":"Customer Outcomes","url":"https://www.scrum.org/resources/customer-outcomes","section":"Determining customer outcomes - getting started; Conclusion","verifiedOn":"2026-10-14","sourceSupport":"Asking customers about their goals and challenges supports discovery of desired outcomes. This does not mandate one discovery technique for all products.","authorityType":"scrum-org-learning-practice"} },
    { id: '13-10', v: 2, d: 'a', t: 'single', b: 'judgment',
      s: "Launchpad's business strategy assumes that more onboarding options improve retention. Experiments show that simpler onboarding helps customers succeed and retain the product. What should the Product Owner do?",
      o: ["Keep the feature roadmap unchanged because strategy cannot change","Share the evidence, reconsider the strategic assumption with relevant stakeholders, and align product goals and backlog choices with what is learned","Let the Scrum Master choose a replacement business strategy","Measure only how many features the team finishes"],
      c: [1],
      e: "Business strategy and product decisions should respond to evidence. Product results can challenge strategic assumptions; stakeholders and teams inspect that evidence and adapt goals and choices.",
      x: "A strategy is a hypothesis about how to achieve goals, not immunity from inspection. The Scrum Master does not take over product strategy, and output counts do not establish customer benefit.",
      src: {"label":"Evidence-Based Management (EBM) and Business Strategy","url":"https://www.scrum.org/resources/evidence-based-management-ebm-and-business-strategy","section":"Opening explanation; organizational, portfolio and product experimentation"} },

    /* ---------- Module 14: Backlog ordering and stakeholders ---------- */
    { id: '14-01', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "Who is accountable for ordering the Product Backlog?",
      o: ["The Developers","The Product Owner","The Scrum Master","Key stakeholders by vote"],
      c: [1],
      e: "Ordering Product Backlog items is part of the Product Owner's accountability.",
      x: "Others can influence the order by convincing the Product Owner, but do not own it.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '14-02', v: 1, d: 'f', t: 'multi', b: 'rule',
      s: "Which three are part of the Product Owner's accountability for effective Product Backlog management?",
      o: ["Developing and explicitly communicating the Product Goal","Sizing Product Backlog items","Creating and clearly communicating Product Backlog items","Creating the Sprint's plan","Ordering Product Backlog items","Ensuring Scrum events take place"],
      c: [0,2,4],
      e: "The four elements are: the Product Goal, creating and communicating items, ordering them, and ensuring the backlog is transparent, visible and understood.",
      x: "Sizing and the Sprint plan belong to the Developers; ensuring events happen belongs to the Scrum Master.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '14-03', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "The Product Owner may delegate Product Backlog management work to others but remains accountable.",
      c: true,
      e: "The Product Owner may do the work or delegate it; regardless, the Product Owner remains accountable.",
      x: "Delegating work does not transfer accountability.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '14-04', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "Sales and Customer Success each insist their request should be next. What should the Product Owner do?",
      o: ["Do whichever request came first","Ask the Scrum Master to decide to avoid conflict","Gather the evidence and reasoning from each, decide the order to maximize value, and explain the decision transparently","Split each Sprint evenly between the two"],
      c: [2],
      e: "The Product Owner represents many stakeholders and makes ordering decisions that the organization must respect. Explaining the reasoning keeps stakeholders engaged and builds trust.",
      x: "Arrival order or a 50/50 split avoids the value decision; the Scrum Master does not own backlog order.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '14-05', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "For the Product Owner to succeed, the Scrum Guide says:",
      o: ["The Product Owner must have a management title","The entire organization must respect their decisions","Stakeholders must approve the Product Backlog quarterly","The Scrum Master must review their decisions"],
      c: [1],
      e: "For Product Owners to succeed, the entire organization must respect their decisions.",
      x: "No title, approval cycle or Scrum Master review is required.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '14-06', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "Which approach to ordering the Product Backlog is most consistent with maximizing value?",
      o: ["Strictly by the size of each item, smallest first","Considering value, risk, cost, dependencies and learning, and adjusting as evidence changes","By the seniority of the person who requested each item","Alphabetically, to stay neutral"],
      c: [1],
      e: "Ordering is a judgment that balances several factors. Sometimes a risky or enabling item comes first because learning early prevents larger waste.",
      x: "Single-factor rules and requester seniority ignore the trade-offs the Product Owner is accountable for.",
      sup: [{"label":"Product Cost","url":"https://www.scrum.org/resources/product-cost","section":"What is Product Cost?; Understanding Product Cost","verifiedOn":"2026-10-14","sourceSupport":"Direct and indirect lifetime costs include development, maintenance, support, employee wages, tools and overhead. Cost can be balanced with learning, risk and expected benefit.","authorityType":"scrum-org-learning-practice"},{"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Hypotheses, Experiments, Features, and Requirements","verifiedOn":"2026-10-14","sourceSupport":"A whole feature need not be built to test critical value assumptions. Customer evidence can come from small experiments.","authorityType":"separate-ebm-framework"}],
      src: {"label":"Ordering the Product Backlog","url":"https://www.scrum.org/resources/ordering-product-backlog","section":"Opening explanation","verifiedOn":"2026-10-14","sourceSupport":"Ordering may consider business value, risk, ROI, dependencies and impact; no single required ordering formula is prescribed.","authorityType":"scrum-org-learning-practice"} },
    { id: '14-07', v: 1, d: 'a', t: 'tf', b: 'judgment',
      s: "The Product Backlog must be ordered strictly by business value.",
      c: false,
      e: "The Guide calls the backlog ordered but does not prescribe criteria. Risk, dependencies, learning and cost can also shape the order.",
      x: "A single criterion can lead to poor decisions, such as postponing a risky item until it is expensive to change course.",
      src: {"label":"Ordering the Product Backlog","url":"https://www.scrum.org/resources/ordering-product-backlog","section":"Opening explanation","verifiedOn":"2026-10-14","sourceSupport":"Ordering may consider business value, risk, ROI, dependencies and impact; no single required ordering formula is prescribed.","authorityType":"scrum-org-learning-practice"} },
    { id: '14-08', v: 2, d: 'c', t: 'single', b: 'judgment',
      s: "A business analyst acts as a proxy for a busy Product Owner. The Product Owner gave no clear delegated authority or ordering intent, then repeatedly reversed the analyst's decisions without new evidence. What is the core problem?",
      o: ["The analyst should be named Product Owner instead","Accountability is unclear: the Product Owner remains accountable and must stay engaged enough that delegated decisions reflect their intent","The Developers should have refused to work with the analyst","The Scrum Master should approve all proxy decisions"],
      c: [1],
      e: "Delegation is allowed, but the Product Owner remains accountable and must make the intended priorities and authority clear. Reversals prompted by new evidence can be healthy adaptation; the missing clarity in this situation creates the problem.",
      x: "Renaming roles or adding approvals does not fix the accountability gap; refusing to work is unhelpful.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '14-09', v: 1, d: 'a', t: 'multi', b: 'rule',
      s: "Where does the Scrum Guide say the Product Owner's decisions are visible?",
      o: ["In the content and ordering of the Product Backlog","In the Scrum Master's reports","Through the inspectable Increment at the Sprint Review","At the Daily Scrum"],
      c: [0,2],
      e: "The Product Owner's decisions are visible in the backlog's content and order and through the inspectable Increment at the Sprint Review.",
      x: "Scrum defines no Scrum Master reports, and the Daily Scrum is for the Developers.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },
    { id: '14-10', v: 1, d: 'a', t: 'single', b: 'rule',
      s: "At Sprint Planning, the Developers find the top backlog items too vague to plan. Who is accountable for clearly communicating Product Backlog items?",
      o: ["The Developers","The Scrum Master","The Product Owner","The stakeholders who requested them"],
      c: [2],
      e: "Creating and clearly communicating Product Backlog items is part of the Product Owner's accountability, even when others help refine them.",
      x: "The Developers help refine and the Scrum Master helps the team understand the need for clear items, but accountability is the Product Owner's.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"} },

    /* ---------- Module 15: Value, economics, and releases ---------- */
    { id: '15-01', v: 1, d: 'f', t: 'single', b: 'rule',
      s: "Which statement about releasing is consistent with the Scrum Guide?",
      o: ["Increments may be released only after the Sprint Review","An Increment may be delivered to stakeholders before the end of the Sprint","Every Increment must be released immediately","Releases happen only at the end of each Product Goal"],
      c: [1],
      e: "An Increment may be delivered before the Sprint ends; the Sprint Review should never be considered a gate to releasing value.",
      x: "Scrum neither requires waiting for the Review nor mandates immediate release of every Increment.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#increment","section":"Increment"} },
    { id: '15-02', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "A feature would please one large customer but would require ongoing maintenance with every partner API change. What should the Product Owner weigh most carefully?",
      o: ["Only the immediate revenue from the customer","The total cost of ownership over the product's life against the expected benefit","How quickly the Developers can build it","Whether the Scrum Master approves"],
      c: [1],
      e: "Features carry ongoing costs — maintenance, support and complexity — that can outweigh their benefits. The Product Owner orders work to maximize value over the product's life.",
      x: "Immediate revenue or build speed alone ignores long-term cost; the Scrum Master does not approve product decisions.",
      src: {"label":"Product Cost","url":"https://www.scrum.org/resources/product-cost","section":"What is Product Cost?; Understanding Product Cost","verifiedOn":"2026-10-14","sourceSupport":"Direct and indirect lifetime costs include development, maintenance, support, employee wages, tools and overhead. Cost can be balanced with learning, risk and expected benefit.","authorityType":"scrum-org-learning-practice"} },
    { id: '15-03', v: 2, d: 'a', t: 'tf', b: 'judgment',
      s: "Removing a rarely used feature can increase a product's overall value.",
      c: true,
      e: "Software features can incur maintenance, support and complexity costs. Removing a low-benefit feature can lower these costs, but inspect removal costs and the needs of customers who still rely on it.",
      x: "Assuming more features always means more value confuses output with value.",
      sup: [{"label":"Product Cost","url":"https://www.scrum.org/resources/product-cost","section":"What is Product Cost?; Understanding Product Cost","verifiedOn":"2026-10-14","sourceSupport":"Direct and indirect lifetime costs include development, maintenance, support, employee wages, tools and overhead. Cost can be balanced with learning, risk and expected benefit.","authorityType":"scrum-org-learning-practice"}],
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Ability to Innovate (A2I); Appendix: Example Key Value Measures — Ability to Innovate (A2I)","verifiedOn":"2026-10-14","sourceSupport":"Poor quality, low-value feature maintenance and systemic impediments can reduce innovation capacity. Appendix examples include technical debt, defect trends and active product/code branches.","authorityType":"separate-ebm-framework"} },
    { id: '15-04', v: 2, d: 'a', t: 'multi', b: 'judgment',
      s: "A proposed feature will increase maintenance work and code complexity. The Scrum Master's salary and existing meeting-room cost will remain unchanged. Which two are additional ongoing costs caused by this feature?",
      o: ["Maintenance and support effort","The unchanged Scrum Master salary","Added complexity that slows future changes","The unchanged meeting-room cost"],
      c: [0,2],
      e: "In this scenario maintenance, support and added complexity are incremental costs of the feature. Total product cost also includes wages and overhead.",
      x: "Salary and room costs remain part of overall product cost. They are excluded here only because the stem explicitly says they do not change with this feature.",
      sup: [{"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Ability to Innovate (A2I); Appendix: Example Key Value Measures — Ability to Innovate (A2I)","verifiedOn":"2026-10-14","sourceSupport":"Poor quality, low-value feature maintenance and systemic impediments can reduce innovation capacity. Appendix examples include technical debt, defect trends and active product/code branches.","authorityType":"separate-ebm-framework"}],
      src: {"label":"Product Cost","url":"https://www.scrum.org/resources/product-cost","section":"What is Product Cost?; Understanding Product Cost","verifiedOn":"2026-10-14","sourceSupport":"Direct and indirect lifetime costs include development, maintenance, support, employee wages, tools and overhead. Cost can be balanced with learning, risk and expected benefit.","authorityType":"scrum-org-learning-practice"} },
    { id: '15-05', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "How does unaddressed technical debt usually affect product value?",
      o: ["It has no effect if customers cannot see it","It slows future delivery and reduces the organization's ability to respond to new opportunities","It increases velocity over time","It only affects the Developers, not the Product Owner"],
      c: [1],
      e: "Technical debt makes change slower and riskier. Making it transparent in the Product Backlog lets the Product Owner order it against other work.",
      x: "Invisible to customers is not the same as harmless; its costs reach the Product Owner's value decisions.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Ability to Innovate (A2I); Appendix: Example Key Value Measures — Ability to Innovate (A2I)","verifiedOn":"2026-10-14","sourceSupport":"Poor quality, low-value feature maintenance and systemic impediments can reduce innovation capacity. Appendix examples include technical debt, defect trends and active product/code branches.","authorityType":"separate-ebm-framework"} },
    { id: '15-06', v: 2, d: 'f', t: 'single', b: 'rule',
      s: "In a complex environment, release forecasts should be based on:",
      o: ["A detailed up-front plan","What has already happened, updated as more is learned","The deadline the stakeholders prefer","The maximum possible velocity"],
      c: [1],
      e: "Only what has already happened may be used for forward-looking decisions in complex environments, so forecasts should be updated as evidence changes.",
      x: "A plan or target date can inform discussion, but is not evidence of future delivery by itself. Forecasts should use relevant observations and state their assumptions rather than assume a best-case rate.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#the-sprint","section":"The Sprint (forecasting)"} },
    { id: '15-07', v: 1, d: 'f', t: 'tf', b: 'rule',
      s: "The Sprint Review is when the Product Owner formally approves Increments for release.",
      c: false,
      e: "The Sprint Review should never be considered a gate to releasing value. It is a working session to inspect the outcome and adapt.",
      x: "Treating it as an approval gate delays value and misrepresents its purpose.",
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#increment","section":"Increment"} },
    { id: '15-08', v: 2, d: 'c', t: 'single', b: 'judgment',
      s: "A stakeholder demands a guarantee that a fixed set of features will ship by a fixed date, although much of the work is uncertain. What is the Product Owner's best response?",
      o: ["Agree, and tell the Developers to reduce testing if needed","Explain the uncertainty, offer an evidence-based forecast with its assumptions, and discuss what scope is most valuable to protect if trade-offs are needed","Refuse to give any forecast","Add more Developers to guarantee the date"],
      c: [1],
      e: "Empirical forecasts are honest about uncertainty. Focusing on the most valuable scope keeps the date discussion grounded without sacrificing quality.",
      x: "Cutting quality conflicts with the Sprint rules. Refusing any forecast loses useful information. Adding people does not establish a delivery guarantee.",
      sup: [{"label":"Introduction to Forecasting and Release Planning","url":"https://www.scrum.org/resources/introduction-forecasting-and-release-planning","section":"Forecasting","verifiedOn":"2026-10-14","sourceSupport":"The Forecasting section supports using known information and delivery trends/history, and explicitly says a forecast is not a commitment or guarantee. It does not derive the course scenario's calendar range.","authorityType":"scrum-org-learning-practice"}],
      src: {"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#the-sprint","section":"The Sprint (forecasting)"} },
    { id: '15-09', v: 1, d: 'a', t: 'single', b: 'judgment',
      s: "What is the main benefit of releasing Done Increments frequently?",
      o: ["It keeps the Developers busy","It shortens feedback loops and lets value be realized sooner, reducing the risk of building the wrong thing","It removes the need for a Sprint Review","It guarantees customer satisfaction"],
      c: [1],
      e: "Frequent releases give earlier evidence of value and earlier benefit, which supports empirical product decisions.",
      x: "The Sprint Review still inspects outcomes and adapts plans; no practice guarantees satisfaction.",
      src: {"label":"Introduction to Forecasting and Release Planning","url":"https://www.scrum.org/resources/introduction-forecasting-and-release-planning","section":"Release Planning","verifiedOn":"2026-10-14","sourceSupport":"Frequent small releases support faster user feedback, learning and course correction and earlier risk discovery. These are potential benefits, not guaranteed customer satisfaction.","authorityType":"scrum-org-learning-practice"} },
    { id: '15-10', v: 2, d: 'a', t: 'multi', b: 'judgment',
      s: "Which two are evidence of customer value rather than output?",
      o: ["Customers complete onboarding faster than before","The number of features shipped this quarter","Support contacts fall because customers complete onboarding unaided, with usage and completion rates stable","Story points completed per Sprint"],
      c: [0,2],
      e: "Faster onboarding and successful unaided completion are evidence about customer outcomes. A falling support-contact count alone could instead reflect fewer users or difficulty reaching support.",
      x: "Features shipped and story points measure how much work was done, not whether customers benefited.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Understanding What is Valuable","verifiedOn":"2026-10-14","sourceSupport":"The guide distinguishes inputs, activities, outputs, customer outcomes and organizational impacts; more features do not necessarily improve customer experiences.","authorityType":"separate-ebm-framework"} },

    /* ---------- Module 16: Evidence-Based Management ---------- */
    { id: '16-01', v: 1, d: 'f', t: 'multi', b: 'concept',
      s: "Which four are the Key Value Areas in Evidence-Based Management?",
      o: ["Current Value","Velocity","Unrealized Value","Ability to Innovate","Return on Effort","Time to Market"],
      c: [0,2,3,5],
      e: "EBM's four Key Value Areas are Current Value, Unrealized Value, Ability to Innovate and Time to Market.",
      x: "Velocity and \"return on effort\" are not Key Value Areas.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"EBM Uses Key Value Areas to Examine Improvement Opportunities","verifiedOn":"2026-10-14","sourceSupport":"CV and UV examine market value; A2I and T2M examine the organization's capability to deliver valuable outcomes.","authorityType":"separate-ebm-framework"} },
    { id: '16-02', v: 1, d: 'f', t: 'single', b: 'concept',
      s: "Which Key Value Area describes the organization's capability to deliver new capabilities that might better meet customer needs?",
      o: ["Current Value","Unrealized Value","Ability to Innovate","Time to Market"],
      c: [2],
      e: "Ability to Innovate concerns how effectively the organization can deliver new capabilities. Technical debt and defect load reduce it.",
      x: "Current and Unrealized Value describe the product's value; Time to Market describes delivery and learning speed.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Ability to Innovate (A2I); Appendix: Example Key Value Measures — Ability to Innovate (A2I)","verifiedOn":"2026-10-14","sourceSupport":"Poor quality, low-value feature maintenance and systemic impediments can reduce innovation capacity. Appendix examples include technical debt, defect trends and active product/code branches.","authorityType":"separate-ebm-framework"} },
    { id: '16-03', v: 1, d: 'f', t: 'tf', b: 'concept',
      s: "Evidence-Based Management is defined in the Scrum Guide.",
      c: false,
      e: "EBM is a separate Scrum.org framework with its own guide. It complements Scrum but is not part of it.",
      x: "Mixing up the two guides can lead to treating EBM terms as Scrum rules.",
      sup: [{"label":"The 2020 Scrum Guide","url":"https://scrumguides.org/scrum-guide.html","section":"Complete framework definition"}],
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Definition of Evidence-Based Management","verifiedOn":"2026-10-14","sourceSupport":"The May 2024 EBM Guide defines its own framework for better-informed decisions using intentional experimentation and feedback.","authorityType":"separate-ebm-framework"} },
    { id: '16-04', v: 1, d: 'a', t: 'single', b: 'concept',
      s: "Many prospects say onboarding takes too long, and competitors are winning those customers. Which Key Value Area does this evidence mainly relate to?",
      o: ["Current Value","Unrealized Value","Ability to Innovate","Time to Market"],
      c: [1],
      e: "Unrealized Value is the potential future value that could be realized by better meeting customer needs, including unmet demand.",
      x: "Current Value is what is delivered today; Ability to Innovate and Time to Market describe the organization's delivery capability.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Unrealized Value (UV)","verifiedOn":"2026-10-14","sourceSupport":"Unmet customer satisfaction gaps identify potential future value; prospects lost to a competitor can provide evidence of that gap.","authorityType":"separate-ebm-framework"} },
    { id: '16-05', v: 1, d: 'f', t: 'single', b: 'concept',
      s: "What is the order of the experiment loop described in EBM?",
      o: ["Build, measure, report, close","Form a hypothesis, run the experiment, inspect the results, adapt","Plan, execute, approve, release","Estimate, commit, deliver, celebrate"],
      c: [1],
      e: "EBM treats steps toward goals as experiments: form a hypothesis, run the experiment, inspect results, and adapt goals or approach.",
      x: "The other sequences lack a testable hypothesis or an adaptation step.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Making Progress Toward Goals in a Series of Small Steps","verifiedOn":"2026-10-14","sourceSupport":"Explicit hypothesis, experiment, result inspection and adaptation form the loop; goals may be changed when learning warrants it.","authorityType":"separate-ebm-framework"} },
    { id: '16-06', v: 1, d: 'a', t: 'single', b: 'concept',
      s: "A team tracks how long it takes from an idea being approved to customers using it, and how often it releases. Which Key Value Area do these measures mainly inform?",
      o: ["Current Value","Unrealized Value","Ability to Innovate","Time to Market"],
      c: [3],
      e: "Time to Market describes how quickly the organization can deliver new capabilities and learn from them; cycle time and release frequency are typical signals.",
      x: "These measures describe speed of delivery and learning, not the value already delivered or the size of unmet demand.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Time-to-Market (T2M); Appendix: Example Key Value Measures — Time-to-Market (T2M)","verifiedOn":"2026-10-14","sourceSupport":"Delivery and learning speed are relevant; appendix examples include release frequency, customer cycle time, lead time and time to learn.","authorityType":"separate-ebm-framework"} },
    { id: '16-07', v: 1, d: 'a', t: 'single', b: 'concept',
      s: "In EBM, what is an Intermediate Goal?",
      o: ["The long-term, aspirational aim","A milestone whose achievement indicates progress toward the Strategic Goal","The daily task list","A goal set for one Developer"],
      c: [1],
      e: "EBM describes a Strategic Goal, Intermediate Goals that mark progress toward it, and Immediate Tactical Goals the team works on now.",
      x: "The long-term aim is the Strategic Goal; task lists and individual goals are not EBM goal levels.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"EBM Helps Organizations Achieve Their Goals in a Complex World","verifiedOn":"2026-10-14","sourceSupport":"Strategic, Intermediate and Immediate Tactical Goals are separate levels. Relevance and progress should be examined; levels are not individual task lists.","authorityType":"separate-ebm-framework"} },
    { id: '16-08', v: 2, d: 'f', t: 'tf', b: 'concept',
      s: "Output measures such as the number of features delivered are reliable evidence of customer value.",
      c: false,
      e: "Features shipped and velocity are outputs, not reliable evidence that customers received value. They may inform delivery capability, but customer outcomes must be inspected separately.",
      x: "More output does not automatically mean more value. Combining capability signals with customer evidence is more informative than treating output as proof of benefit.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Understanding What is Valuable","verifiedOn":"2026-10-14","sourceSupport":"The guide distinguishes inputs, activities, outputs, customer outcomes and organizational impacts; more features do not necessarily improve customer experiences.","authorityType":"separate-ebm-framework"} },
    { id: '16-09', v: 2, d: 'c', t: 'single', b: 'judgment',
      s: "Defect fixes consume about a third of every Sprint, and new features are increasingly slow to deliver. What is the Product Owner's best response?",
      o: ["Ignore it; only new features create value","Investigate the causes and consider appropriate quality or debt-reduction work in the Product Backlog to improve Ability to Innovate","Ask the Developers to fix defects outside working hours","Treat it only as a Time to Market metric"],
      c: [1],
      e: "The defect load is a warning about Ability to Innovate. Investigate its causes and make suitable improvement work transparent; it does not by itself prove that technical debt is the cause.",
      x: "Ignoring defect work does not protect value. Requiring fixes outside working hours undermines a sustainable pace. Defect load can affect several value areas; treating it only as Time to Market misses its effect on Ability to Innovate.",
      sup: [{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#product-owner","section":"Product Owner"},{"label":"Scrum Guide","url":"https://scrumguides.org/scrum-guide.html#scrum-team","section":"Scrum Team (sustainable pace)"}],
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Ability to Innovate (A2I); Appendix: Example Key Value Measures — Ability to Innovate (A2I)","verifiedOn":"2026-10-14","sourceSupport":"Poor quality, low-value feature maintenance and systemic impediments can reduce innovation capacity. Appendix examples include technical debt, defect trends and active product/code branches.","authorityType":"separate-ebm-framework"} },
    { id: '16-10', v: 2, d: 'c', t: 'single', b: 'judgment',
      s: "An experiment increased feature adoption from 12% to 35%, but the target outcome — faster time to first month-end close — did not change. What should the Product Owner do next?",
      o: ["Celebrate adoption and continue the same plan","Inspect why the intended outcome did not improve, adapt the next experiment and backlog, and keep the feature only if evidence supports its usefulness","Abandon the Product Goal immediately","Replace the outcome measure with adoption to make the experiment a success"],
      c: [1],
      e: "Inspect the intended customer outcome rather than substitute a convenient proxy. Change the approach based on evidence; one unsuccessful experiment does not establish that the goal is obsolete.",
      x: "Declaring success confuses a proxy with the goal; abandoning the goal or repeating the same experiment ignores what was learned.",
      src: {"label":"Evidence-Based Management Guide (May 2024)","url":"https://www.scrum.org/resources/online-evidence-based-management-guide","section":"Inspecting and Adapting Based on Experiment Results","verifiedOn":"2026-10-14","sourceSupport":"Inspect results against goals. Failed experiments guide new experiments; goals may change if obsolete or needing refinement, not merely because one tactic failed.","authorityType":"separate-ebm-framework"} },
  ]);
})(typeof window !== 'undefined' ? window : globalThis);
